def count_numbers_with_digit_sum(target):
    count = 0
    # We consider numbers with up to 7 digits (since 1,000,000 has 7 digits)
    for length in range(1, 7):
        for digits in product(range(10), repeat=length):
            if sum(digits) == target:
                # Ensure the number does not start with a zero
                if digits[0] == 0:
                    continue
                count += 1
    return count

